// tag, so a name is spliced whole.)
const r = (i) => `r${i}`;
const m = (i) => `m${i}`;
const s = (j) => `s${j}`;
const v = (j) => `v${j}`;
// Conditions, all of them; none is true.
const all = (xs) => (xs.length ? `${((items, sep = "\n") => Array.from(items, String).join(sep))(xs, " && ")}` : `true`);

